      ally_down: ["Another debt. Lanka keeps count."],
      defeat: ["Avenge me... Ravana..."],
      victory: ["Now we are even. Almost."],
      parried: ["Clever. I will remember clever."],
      climb: ["I walked the whole forest looking for him."],
      fall: ["Not my face. Not again."],
      slammed: ["You will regret touching me."],
      terrain: ["The Dandaka forest was mine before it was theirs."],
      player_correct: ["Sharp. Like a blade. I know about blades."],
      player_wrong: ["Wrong. And rude."],
      rethink: ["Then I will find another way to hurt you."],
      dream_opened: ["A dream? I can wear any face in a dream."],
