      low_lf: ["Return her. It is not too late. It is never too late."],
      reveal: ["I saw this in a dream three nights ago."],
      ultimate: ["Listen to me, all of you. Just this once."],
      ally_down: ["I told you. I told you, and you would not listen."],
      defeat: ["Lanka... my husband... I tried."],
      victory: ["A victory. For today."],
      parried: ["You see it too, then."],
      climb: ["A queen climbs the stairs of her own tower every day."],
      fall: ["Not yet. There is still something to say."],
      slammed: ["You cannot frighten me more than the truth does."],
      terrain: ["Every road out of Lanka ends the same way."],
      player_correct: ["Yes. You understand."],
